use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width = 0
    let mut line = ""
    let mut have = false
    for l in text.lines() {
        if first {
            first = false
            match l.trim().parse::<int>() {
                Ok(n) => { width = n }
                Err(_) => { width = 0 }
            }
            if width <= 0 {
                println("error: bad width")
                std::process::exit(1)
            }
        } else {
            for w in l.split_whitespace() {
                if !have {
                    line = w
                    have = true
                } else if (line.len() as int) + 1 + (w.len() as int) <= width {
                    line = "${line} ${w}"
                } else {
                    println(line)
                    line = w
                }
            }
        }
    }
    if first {
        println("error: bad width")
        std::process::exit(1)
    }
    if have {
        println(line)
    }
}

